public class InterestCalculator {
    public static void main(String[] args) {
        double principal = 500000.0;  // ₹5 Lakh loan
        double rate = 0.09;           // 9% per annum
        int years = 3;

        // Simple Interest: P * R * T / 100 (using rate as fraction)
        double simpleInterest = principal * rate * years;
        System.out.printf("Simple Interest: ₹%.2f%n", simpleInterest);

        // Compound Interest: P * (1 + r)^t - P
        double amount = principal * Math.pow(1 + rate, years);
        double compoundInterest = amount - principal;
        System.out.printf("Compound Interest: ₹%.2f%n", compoundInterest);
        System.out.printf("Difference (Compound vs Simple): ₹%.2f%n",
                          compoundInterest - simpleInterest);

        // Ternary: loan category
        String loanCategory = (principal <= 200000) ? "PERSONAL" :
                              (principal <= 1000000) ? "HOME_SMALL" : "HOME_LARGE";
        System.out.println("Loan Category: " + loanCategory);
    }
}

