public class ATMSimulator {
    public static void main(String[] args) {
        double balance = 25000.0;
        int correctPIN = 1234;
        int attempts = 0;
        boolean authenticated = false;

        // Do-while: show prompt at least once; useful for retry loops
        int[] pinAttempts = {1234, 9999, 5678}; // simulating user inputs
        int inputIdx = 0;

        do {
            int enteredPIN = pinAttempts[inputIdx++];
            attempts++;
            if (enteredPIN == correctPIN) {
                authenticated = true;
                System.out.println("PIN correct. Welcome!");
            } else {
                System.out.println("Incorrect PIN. Attempt " + attempts + " of 3.");
            }
        } while (!authenticated && attempts < 3);

        if (!authenticated) {
            System.out.println("Card blocked after 3 failed attempts.");
            return;
        }

        // Process withdrawal transactions
        double[] withdrawals = {5000, 30000, 1000, 0};  // 0 = exit
        for (double amount : withdrawals) {
            if (amount == 0) {
                System.out.println("Thank you. Goodbye!");
                break;  // exit loop
            }
            if (amount > balance) {
                System.out.printf("Insufficient funds. Balance: ₹%.2f%n", balance);
                continue;  // skip this withdrawal, try next
            }
            balance -= amount;
            System.out.printf("Dispensed ₹%.0f. Remaining balance: ₹%.2f%n", amount, balance);
        }
    }
}

