import java.util.Arrays;

public class BranchAnalysis {
    public static void main(String[] args) {
        String[] branches = {"Mumbai", "Delhi", "Kolkata", "Chennai", "Hyderabad"};
        double[] deposits = {8500000, 12300000, 6700000, 9200000, 11100000}; // in rupees

        // Total deposits
        double total = 0;
        for (double d : deposits) total += d;
        System.out.printf("Total Deposits: ₹%.2f%n", total);
        System.out.printf("Average Deposits: ₹%.2f%n", total / deposits.length);

        // Sort deposits (Arrays.sort modifies the array in place)
        double[] sortedDeposits = Arrays.copyOf(deposits, deposits.length); // don't modify original
        Arrays.sort(sortedDeposits);
        System.out.printf("Lowest performing branch deposit: ₹%.2f%n", sortedDeposits[0]);
        System.out.printf("Highest performing branch deposit: ₹%.2f%n",
                          sortedDeposits[sortedDeposits.length - 1]);

        // Find a branch by deposit (binary search on sorted array)
        double target = 9200000;
        int idx = Arrays.binarySearch(sortedDeposits, target);
        System.out.println("Search result index (sorted array): " + idx);

        // Find branch name with max deposit (manual)
        int maxIdx = 0;
        for (int i = 1; i < deposits.length; i++) {
            if (deposits[i] > deposits[maxIdx]) maxIdx = i;
        }
        System.out.println("Best performing branch: " + branches[maxIdx]);

        System.out.println("All deposits: " + Arrays.toString(deposits));
    }
}

public class TransactionAggregator {

    // varargs parameter (must be last, type followed by ...)
    public static double sumTransactions(String accountId, double... amounts) {
        double total = 0;
        for (double amount : amounts) {
            total += amount;
        }
        System.out.printf("Account %s | %d transactions | Total: ₹%.2f%n",
                          accountId, amounts.length, total);
        return total;
    }

    public static void main(String[] args) {
        sumTransactions("ACC001");                          // 0 transactions
        sumTransactions("ACC002", 5000);                    // 1 transaction
        sumTransactions("ACC003", 1000, 2500, 750);         // 3 transactions
        sumTransactions("ACC004", 10000, 5000, 3000, 1500, 250); // 5 transactions
    }
}

